style.css:
@-moz-document url("https://ixl.com") {
body {
    font: 13px Verdana, ariel, helvetica, clean, sans-serif;
    font-family: Verdana, ariel, helvitica, clean, sans-serif;
    font-size: 13px;
    font-style: normal;
    font-variant: normal;
    font-weight: normal;
    font-stretch: normal;
    line-height: normal;
    background: rgb(7, 28, 59);
}

#hd, #banners-wrapper, .site-nav-header-container, .box-site-nav-func, .site-nav-header, .add-to-zindex-calculation, .site-nav-2022, .consolidated::before, .dashboard-module, .module-container, .short, .recommendation-area {
	background-color: rgb(7, 28, 59) !important;
}

.crisp-button {
	background-color: rgb(232, 232, 232) !important;
  	color: black !important;
}

.crisp-button:hover {
	background-color: transparent !important;
  	color: black !important;
  	border-left: 3px solid;
  	border-left-color: rgb(7, 28, 59) !important;
}

.site-nav-footer {
	display: none;
}

.category-menu, .hover-active {
	border-bottom-left-radius: 20px !important;
  	border-bottom-right-radius: 20px !important;
  	border: 3px solid;
  	border-left-color: rgb(35, 0, 110) !important;
  	border-bottom-color: rgb(35, 0, 110) !important;
  	border-right-color: transparent !important;
  	background-color: rgb(6, 35, 77) !important;
}

.suggestion-card, .student-suggested-skills-entry {
	background-color: rgb(6, 35, 77) !important;
}

.items {
	background-color: transparent !important;
}

.suggestion-toggle-bar {
	border-radius: 10px !important;
}

.suggestions-tab, .recent-skills-tab, .recommendations-tab {
  	border-radius: 10px;
}

.student-stats, .student-stats-container, .student-stats-header, .student-stats-content, .student-progress-container {
  	background: none;
  	background-color: rgb(7, 28, 59) !important;
  	border-radius: 10px !important;
}

#bd, .student-summary-report, .student-summary-diagnostic-section {
  	background: none !important;
	background-color: rgb(6, 35, 77) !important;
}

.report-title {
	color: white !important;
}

.dashboard-module, .module-container, .short {
	margin-top: 15px;
  	border-radius: 10px !important;
}
}
